import * as T from './vendor/three.module.min.js';
const textures={};
const names=['limestone-dry','limestone-wet','riverbed-pebbles','tufa-step','aged-copper-verdigris','handworked-ladle-wood','worn-cotton-terry','mineral-waterline-scale'];
export async function initializeSpringTextures(decode){const jobs=[...['limestone-strata','limestone-flowstone','mineral-poolbed','spring-ripples','waterfall-flow','water-caustics'].map(n=>[n,'./textures/level27/'+n+'.webp',!['spring-ripples','waterfall-flow','water-caustics'].includes(n)]),...names.flatMap(n=>['','-normal','-roughness','-ao'].map(s=>[n+s,'./textures/spring-v63/'+n+s+'.webp',s==='']))];await Promise.all(jobs.map(async([name,path,color])=>{const url=new URL(path,import.meta.url);let t;if(decode){const im=await decode(url,512,512);t=new T.DataTexture(im.data,im.width,im.height);t.flipY=true;t.needsUpdate=true;}else t=await new T.TextureLoader().loadAsync(url.href);t.wrapS=t.wrapT=T.RepeatWrapping;t.minFilter=T.LinearMipmapLinearFilter;t.magFilter=T.LinearFilter;t.generateMipmaps=true;t.colorSpace=color?T.SRGBColorSpace:T.NoColorSpace;t.anisotropy=8;t.name=name;textures[name]=t;}));}
export function springTextures(){return textures;}
export function springMaterials(){const make=(name,color=0xffffff,roughness=.8,metalness=0)=>new T.MeshStandardMaterial({name:'Spring / '+name,map:textures[name],normalMap:textures[name+'-normal'],normalScale:new T.Vector2(.85,.85),roughnessMap:textures[name+'-roughness'],aoMap:textures[name+'-ao'],aoMapIntensity:.35,color,roughness,metalness,side:T.DoubleSide});const rock=make('limestone-dry'),wetRock=make('limestone-wet',0xd1dfd3,.13),step=make('tufa-step',0xcbd1c7,.72);return {rock,wetRock,step,calcite:step,bed:make('riverbed-pebbles',0xb2c9b8,.42),copper:make('aged-copper-verdigris',0xffffff,.42,.76),wood:make('handworked-ladle-wood',0xcbbfa8,.55),towel:make('worn-cotton-terry',0xe5ded0,.99),scale:make('mineral-waterline-scale',0xa8b4a6,.15),metal:make('aged-copper-verdigris',0xb9aa80,.38,.75),concrete:step,black:make('limestone-wet',0x101613,.9),lamp:new T.MeshBasicMaterial({color:0xffd7a0})};}
